 "content": "def transform(grid):
    """Continue any down-going diagonal run of a non-background color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Each diagonal pair defines a ray continuing downward in the same direction.
    rays = set()
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r + 1][c2] == color:
                    rays.add((r + 1, c2, dc, color))
    # Extend from the lower member of each diagonal pair to the grid edge.
    for r, c, dc, color in rays:
        rr, cc = r + 1, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == bg:
                out[rr][cc] = color
            rr += 1
            cc += dc
    return out
